WITH metrics AS (SELECT *, NTILE(10) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id) AS duration_sec_bucket, LAST_VALUE(duration_sec, TRUE) OVER (ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_duration_sec, FIRST_VALUE(duration_sec, TRUE) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, MAX(duration_sec) OVER (PARTITION BY page) AS page_max_duration_sec, LAG(duration_sec, 1) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS prev_duration_sec FROM web_events) SELECT session_id, page, event_type, COUNT(CASE WHEN event_type = 'search' THEN 1 END) AS search_count, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, GROUPING(session_id) AS grouping_id FROM metrics GROUP BY GROUPING SETS ((session_id, page, event_type), (session_id, page), (session_id), ()) HAVING COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) < 1000 ORDER BY session_id DESC NULLS LAST;
